import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.D9E58p8B.js";const u=JSON.parse('{"title":"MCP tools reference","description":"","frontmatter":{"title":"MCP tools reference"},"headers":[],"relativePath":"en/reference/index.md","filePath":"en/reference/index.md"}'),r={name:"en/reference/index.md"};function n(i,t,s,c,l,h){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="mcp-tools-reference" tabindex="-1">MCP tools reference <a class="header-anchor" href="#mcp-tools-reference" aria-label="Permalink to &quot;MCP tools reference&quot;">​</a></h1><p>This section describes the 33 public tools that Daimon exposes to your AI client through the MCP protocol, over stdio. Daimon is a local organ of perception and action: it calls no AI itself and only answers when your client queries it.</p><p>The default values quoted are those in the code; if they differ, the code is authoritative.</p><h2 id="the-organs" tabindex="-1">The organs <a class="header-anchor" href="#the-organs" aria-label="Permalink to &quot;The organs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Organ</th><th>Role</th><th>Tools</th><th>Page</th></tr></thead><tbody><tr><td>Vue (Sight)</td><td>See the screen: captures, coordinate conversion, text location, display profiles</td><td>8</td><td><a href="./vue.html">Vue</a></td></tr><tr><td>Touché (Touch)</td><td>Read the accessibility tree: elements, roles, labels</td><td>2</td><td><a href="./touche.html">Touché</a></td></tr><tr><td>Mains (Hands)</td><td>Act: click, type, scroll, drag, drive windows</td><td>15</td><td><a href="./mains.html">Mains</a></td></tr><tr><td>Overlay</td><td>Show the person in front of the screen what the AI is doing</td><td>5</td><td><a href="./overlay.html">Overlay</a></td></tr><tr><td>Diagnostic</td><td>Check the state of the machine and the authorization ceiling</td><td>2, plus <code>ping</code></td><td><a href="./diagnostic.html">Diagnostic</a></td></tr></tbody></table><h2 id="the-33-tools" tabindex="-1">The 33 tools <a class="header-anchor" href="#the-33-tools" aria-label="Permalink to &quot;The 33 tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Organ</th><th>Required level</th></tr></thead><tbody><tr><td><code>vue_displays</code></td><td>Vue</td><td>read</td></tr><tr><td><code>vue_snapshot</code></td><td>Vue</td><td>read</td></tr><tr><td><code>vue_resolve</code></td><td>Vue</td><td>read</td></tr><tr><td><code>vue_find</code></td><td>Vue</td><td>read</td></tr><tr><td><code>vue_calibrate</code></td><td>Vue</td><td>read (saves a display profile)</td></tr><tr><td><code>vue_profile</code></td><td>Vue</td><td>read</td></tr><tr><td><code>vue_profile_brief</code></td><td>Vue</td><td>read</td></tr><tr><td><code>vue_pilot_brief</code></td><td>Vue</td><td>read</td></tr><tr><td><code>touche_tree</code></td><td>Touché</td><td>read</td></tr><tr><td><code>touche_probe</code></td><td>Touché</td><td>read</td></tr><tr><td><code>main_navigate</code></td><td>Mains</td><td>L1</td></tr><tr><td><code>main_hover</code></td><td>Mains</td><td>L1</td></tr><tr><td><code>main_activate</code></td><td>Mains</td><td>L1</td></tr><tr><td><code>main_window_minimize</code></td><td>Mains</td><td>L1</td></tr><tr><td><code>main_window_hide</code></td><td>Mains</td><td>L1</td></tr><tr><td><code>main_window_show</code></td><td>Mains</td><td>L1</td></tr><tr><td><code>main_click</code></td><td>Mains</td><td>L2</td></tr><tr><td><code>main_type</code></td><td>Mains</td><td>L2</td></tr><tr><td><code>main_drag</code></td><td>Mains</td><td>L2</td></tr><tr><td><code>main_key</code></td><td>Mains</td><td>L2</td></tr><tr><td><code>main_press</code></td><td>Mains</td><td>L3</td></tr><tr><td><code>main_mouse_down</code></td><td>Mains</td><td>L4</td></tr><tr><td><code>main_mouse_up</code></td><td>Mains</td><td>L4</td></tr><tr><td><code>main_key_down</code></td><td>Mains</td><td>L4</td></tr><tr><td><code>main_key_up</code></td><td>Mains</td><td>L4</td></tr><tr><td><code>overlay_highlight</code></td><td>Overlay</td><td>none (presentation)</td></tr><tr><td><code>overlay_spotlight</code></td><td>Overlay</td><td>none (presentation)</td></tr><tr><td><code>overlay_cursor</code></td><td>Overlay</td><td>none (presentation)</td></tr><tr><td><code>overlay_banner</code></td><td>Overlay</td><td>none (presentation)</td></tr><tr><td><code>overlay_clear</code></td><td>Overlay</td><td>none (presentation)</td></tr><tr><td><code>daimon_doctor</code></td><td>Diagnostic</td><td>read</td></tr><tr><td><code>main_ceiling</code></td><td>Diagnostic</td><td>read</td></tr><tr><td><code>ping</code></td><td>Diagnostic (appendix)</td><td>read</td></tr></tbody></table><h2 id="authorization-levels" tabindex="-1">Authorization levels <a class="header-anchor" href="#authorization-levels" aria-label="Permalink to &quot;Authorization levels&quot;">​</a></h2><p>Perception, overlay and diagnostic tools are never subject to the ceiling. Only the 15 action tools of Mains are. The ceiling is a human setting: an AI can never raise it, and a tool above the ceiling is refused.</p><table tabindex="0"><thead><tr><th>Level</th><th>Internal name</th><th>What it allows</th></tr></thead><tbody><tr><td>L0</td><td><code>READ</code></td><td>Looking only, no action</td></tr><tr><td>L1</td><td><code>NONDESTRUCTIVE</code></td><td>Scrolling, hovering, activating and hiding windows</td></tr><tr><td>L2</td><td><code>INPUT</code></td><td>Click, typing, keys, drag and drop</td></tr><tr><td>L3</td><td><code>VALIDATION</code></td><td>Activating a committing button (<code>main_press</code>)</td></tr><tr><td>L4</td><td><code>AUTONOMOUS</code></td><td>Low-level primitives: holding the mouse and keys</td></tr></tbody></table><p>The effective level of a call can be raised by the target (for example, a drop onto the Trash), but never lowered below the nominal level in the table above. An unknown tool name is treated as a read and never raises the ceiling. To find out the active ceiling, call <code>main_ceiling</code> (see <a href="./diagnostic.html">Diagnostic</a>).</p><h2 id="common-conventions" tabindex="-1">Common conventions <a class="header-anchor" href="#common-conventions" aria-label="Permalink to &quot;Common conventions&quot;">​</a></h2><p><strong>Coordinates.</strong> Vue and Mains speak in <strong>points</strong>: the unit of the global desktop, the one returned by <code>vue_find</code> and <code>vue_resolve</code> and used by the pointer. On a Retina display, one point corresponds to several pixels of the served image; <code>image_scale</code> gives the number of image pixels <strong>per point</strong>. On Windows, a point is a physical pixel of the virtual screen and <code>backing_scale</code> is always 1.0. Overlay coordinates, by contrast, are raw global pixels: see <a href="./overlay.html">Overlay</a>.</p><p><strong>Region.</strong> A <code>region</code> parameter is a rectangle <code>{x, y, width, height}</code> in points, <strong>local to the chosen display</strong> (the origin is the top-left corner of that display, not of the desktop). It is clamped to the display; a rectangle of zero area captures nothing.</p><p><strong>Image space.</strong> The Mains tools that take a point accept <code>space=&quot;image&quot;</code> with <code>display=k</code>: you give the pixels of a <code>vue_snapshot</code> and Daimon resolves the global point itself. Pass the same <code>max_width</code> and <code>region</code> as the snapshot.</p><p><strong>Responses.</strong> Responses are structured JSON objects. An error from the Vue organ or from point resolution takes the form <code>{&quot;error&quot;: &quot;&lt;code&gt;&quot;, &quot;message&quot;: &quot;&lt;detail&gt;&quot;}</code>. Mains returns <code>{&quot;status&quot;: &quot;refused&quot; | &quot;done&quot; | &quot;error&quot;, ...}</code>: see <a href="./mains.html">Mains</a>.</p><p><strong>Presence on screen.</strong> Every tool call first lights up the presence mark, so that the person in front of the screen knows an AI is using Daimon, whether to look or to act.</p><p><strong>Privacy.</strong> Applications protected by your exclusions are censored in captures, and sensitive content is redacted from accessibility trees. The text typed by <code>main_type</code> is never written to the audit log.</p>',18)])])}const g=e(r,[["render",n]]);export{u as __pageData,g as default};
